mapper.select:
SELECT
    COALESCE(SUM(CASE WHEN food_comment_score BETWEEN 4 AND 5 THEN 1 ELSE 0 END), 0) AS goodCommentCount,
    COALESCE(SUM(CASE WHEN food_comment_score BETWEEN 2 AND 3 THEN 1 ELSE 0 END), 0) AS neutralCommentCount,
    COALESCE(SUM(CASE WHEN food_comment_score BETWEEN 0 AND 1 THEN 1 ELSE 0 END), 0) AS badCommentCount,
    COALESCE(SUM(CASE WHEN food_comment_score BETWEEN 0 AND 1 AND reply_status = 1 THEN 1 ELSE 0 END), 0) AS repliedBadCommentCount
FROM mt_comment
WHERE shop_id = #{shopId}
  AND create_time >= #{from}
  AND create_time < #{to}

mapper.update:
UPDATE mt_comment
SET auto_reply_status = 'FAILED',
    auto_reply_error = #{error},
    update_time = #{updateTime}
WHERE id = #{id}
